import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); PrintWriter out = new PrintWriter(System.out); int t = Integer.parseInt(br.readLine()); while (t-- > 0) { int n = Integer.parseInt(br.readLine()); String s = br.readLine(); boolean hasZero = false; for (int i = 0; i < n; i++) { if (s.charAt(i) == '0') { hasZero = true; break; } } if (!hasZero) { out.println(1); } else { if (s.equals("101")) { out.println(2); } else { out.println(1); } } } out.flush(); out.close(); } }